// The Rust core's Kotlin bindings (generated by core/scripts/build-android.sh, never edited by
// hand) and its native libraries: the .so files in src/androidMain/jniLibs, the host's library
// for JVM tests in build/host.
plugins {
    kotlin("multiplatform")
    id("com.android.library")
}

kotlin {
    jvmToolchain(17)
    jvm()
    androidTarget()

    sourceSets {
        // JNA: the jar on the JVM, the aar (with its native dispatch library) on Android.
        commonMain.dependencies {
            compileOnly("net.java.dev.jna:jna:5.17.0")
        }
        jvmMain.dependencies {
            implementation("net.java.dev.jna:jna:5.17.0")
        }
        androidMain.dependencies {
            implementation("net.java.dev.jna:jna:5.17.0@aar")
        }
        jvmTest.dependencies {
            implementation(kotlin("test"))
        }
    }
}

android {
    namespace = "org.orbtchess.orbt.core"
    compileSdk = 36
    defaultConfig {
        minSdk = 29
        consumerProguardFiles("consumer-rules.pro")
    }
}

// JVM tests load the host's library that build-android.sh puts in build/host.
tasks.withType<Test>().configureEach {
    systemProperty("jna.library.path", layout.buildDirectory.dir("host").get().asFile.path)
}
